<section class="page narrow"><div class="eyebrow small">E’LONLAR</div><h1><?=$item?'E’lonni tahrirlash':'Yangi e’lon berish'?></h1><form class="panel app-form" action="<?=url('listing-save')?>" method="post" data-validate><?=csrf()?><?php if($item):?><input type="hidden" name="id" value="<?=$item['id']?>"><?php endif?><label>Sarlavha<input name="title" required minlength="5" maxlength="120" value="<?=e($item['title']??'')?>"></label><div class="form-row"><label>Toifa<select name="category_id" required><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=($item['category_id']??null)==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach?></select></label><label>Hudud<select name="city" required><?php foreach(['Toshkent','Samarqand','Buxoro','Andijon','Farg‘ona','Namangan']as $c):?><option <?=($item['city']??'')===$c?'selected':''?>><?=e($c)?></option><?php endforeach?></select></label></div><div class="form-row"><label>Narx (so‘m)<input name="price" type="number" min="0" max="999999999999" step="0.01" required value="<?=e($item['price']??0)?>"></label><label>Telefon<input name="phone" type="tel" required pattern="[+0-9 ()\-]{9,25}" maxlength="25" value="<?=e($item['phone']??'+998 ')?>"></label></div><label>Tavsif<textarea name="description" required minlength="15" maxlength="5000" rows="5"><?=e($item['description']??'')?></textarea></label><label>Amal qilish muddati<input name="expires_at" type="date" required min="<?=date('Y-m-d')?>" max="<?=date('Y-m-d',strtotime('+180 days'))?>" value="<?=e(isset($item['expires_at'])&&strtotime($item['expires_at'])>time()?substr($item['expires_at'],0,10):date('Y-m-d',strtotime('+30 days')))?>" data-expiry></label><p id="expiry-hint" class="muted" aria-live="polite"></p><p class="muted">Rasm, PDF yoki videoni e’lon saqlangandan keyin biriktiring.</p><button class="primary">E’lonni saqlash <?=icon('arrow')?></button></form></section>
